def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 7]
    if h >= w:
        cells.sort(key=lambda p: (p[1], p[0]))
    colors = (2, 8, 5)
    result = [row[:] for row in grid]
    for i, (r, c) in enumerate(cells):
        result[r][c] = colors[i % 3]
    return result
